20	import * as zrUtil from 'zrender/src/core/util';
21	import * as graphic from '../../util/graphic';
22	import { toggleHoverEmphasis, SPECIAL_STATES, DISPLAY_STATES } from '../../util/states';
23	import { createTextStyle } from '../../label/labelStyle';
24	import { TreeNode } from '../../data/Tree';
25	import SunburstSeriesModel, { SunburstSeriesNodeItemOption, SunburstSeriesOption } from './SunburstSeries';
26	import GlobalModel from '../../model/Global';
27	import { PathStyleProps } from 'zrender/src/graphic/Path';
28	import { ColorString } from '../../util/types';
29	import Model from '../../model/Model';
30	import { getECData } from '../../util/innerStore';
31	import { getSectorCornerRadius } from '../helper/sectorHelper';
32	import { createOrUpdatePatternFromDecal } from '../../util/decal';
33	import ExtensionAPI from '../../core/ExtensionAPI';
34	import { saveOldStyle } from '../../animation/basicTransition';
35	import { normalizeRadian } from 'zrender/src/contain/util';
36	import { isRadianAroundZero } from '../../util/number';
37	
38	const DEFAULT_SECTOR_Z = 2;
39	const DEFAULT_TEXT_Z = 4;
40	interface DrawTreeNode extends TreeNode {
41	    piece: SunburstPiece
42	}
43	/**
44	 * Sunburstce of Sunburst including Sector, Label, LabelLine
45	 */
46	class SunburstPiece extends graphic.Sector {
47	
48	    node: TreeNode;
49	
50	    private _seriesModel: SunburstSeriesModel;
51	    private _ecModel: GlobalModel;
52	
53	    constructor(node: TreeNode, seriesModel: SunburstSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
54	        super();
55	
56	        this.z2 = DEFAULT_SECTOR_Z;
57	        this.textConfig = {
58	            inside: true
59	        };
60	
61	        getECData(this).seriesIndex = seriesModel.seriesIndex;
62	
63	        const text = new graphic.Text({
64	            z2: DEFAULT_TEXT_Z,
65	            silent: node.getModel<SunburstSeriesNodeItemOption>().get(['label', 'silent'])
66	        });
67	        this.setTextContent(text);
68	
69	        this.updateData(true, node, seriesModel, ecModel, api);
70	    }
71	
72	    updateData(
73	        firstCreate: boolean,
74	        node: TreeNode,
75	        // state: 'emphasis' | 'normal' | 'highlight' | 'downplay',
76	        seriesModel: SunburstSeriesModel,
77	        ecModel: GlobalModel,
78	        api: ExtensionAPI
79	    ) {
80	        this.node = node;
81	        (node as DrawTreeNode).piece = this;
82	
83	        seriesModel = seriesModel || this._seriesModel;
84	        ecModel = ecModel || this._ecModel;
85	
86	        const sector = this;
87	        getECData(sector).dataIndex = node.dataIndex;
88	
89	        const itemModel = node.getModel<SunburstSeriesNodeItemOption>();
90	        const emphasisModel = itemModel.getModel('emphasis');
91	        const layout = node.getLayout();
92	
93	        const sectorShape = zrUtil.extend({}, layout);
94	        sectorShape.label = null;
95	
96	        const normalStyle = node.getVisual('style') as PathStyleProps;
97	        normalStyle.lineJoin = 'bevel';
98	
99	        const decal = node.getVisual('decal');
100	        if (decal) {
101	            normalStyle.decal = createOrUpdatePatternFromDecal(decal, api);
102	        }
103	
104	        const cornerRadius = getSectorCornerRadius(itemModel.getModel('itemStyle'), sectorShape, true);
105	        zrUtil.extend(sectorShape, cornerRadius);
106	
107	        zrUtil.each(SPECIAL_STATES, function (stateName) {
108	            const state = sector.ensureState(stateName);
109	            const itemStyleModel = itemModel.getModel([stateName, 'itemStyle']);
110	            state.style = itemStyleModel.getItemStyle();
111	            // border radius
112	            const cornerRadius = getSectorCornerRadius(itemStyleModel, sectorShape);
113	            if (cornerRadius) {
114	                state.shape = cornerRadius;
115	            }
116	        });
117	
118	        if (firstCreate) {
119	            sector.setShape(sectorShape);
120	            sector.shape.r = layout.r0;
121	            graphic.initProps(
122	                sector,
123	                {
124	                    shape: {
125	                        r: layout.r
126	                    }
127	                },
128	                seriesModel,
129	                node.dataIndex
130	            );
131	        }
132	        else {
133	            // Disable animation for gradient since no interpolation method
134	            // is supported for gradient
135	            graphic.updateProps(sector, {
136	                shape: sectorShape
137	            }, seriesModel);
138	
139	            saveOldStyle(sector);
140	        }
141	
142	        sector.useStyle(normalStyle);
143	
144	        this._updateLabel(seriesModel);
145	
146	        const cursorStyle = itemModel.getShallow('cursor');
147	        cursorStyle && sector.attr('cursor', cursorStyle);
148	
149	        this._seriesModel = seriesModel || this._seriesModel;
150	        this._ecModel = ecModel || this._ecModel;
151	
152	        const focus = emphasisModel.get('focus');
153	
154	        const focusOrIndices = focus === 'relative'
155	            ? zrUtil.concatArray(node.getAncestorsIndices(), node.getDescendantIndices())
156	            : focus === 'ancestor' ? node.getAncestorsIndices()
157	                : focus === 'descendant' ? node.getDescendantIndices()
158	                    : focus;
159	
160	        toggleHoverEmphasis(this, focusOrIndices, emphasisModel.get('blurScope'), emphasisModel.get('disabled'));
161	    }
162	
163	    _updateLabel(
164	        seriesModel: SunburstSeriesModel
165	    ) {
166	        const itemModel = this.node.getModel<SunburstSeriesNodeItemOption>();
167	        const normalLabelModel = itemModel.getModel('label');
168	
169	        const layout = this.node.getLayout();
170	        const angle = layout.endAngle - layout.startAngle;
171	
172	        const midAngle = (layout.startAngle + layout.endAngle) / 2;
173	        const dx = Math.cos(midAngle);
174	        const dy = Math.sin(midAngle);
175	
176	        const sector = this;
177	        const label = sector.getTextContent();
178	        const dataIndex = this.node.dataIndex;
179	        const labelMinAngle = normalLabelModel.get('minAngle') / 180 * Math.PI;
180	        const isNormalShown = normalLabelModel.get('show')
181	            && !(labelMinAngle != null && Math.abs(angle) < labelMinAngle);
182	        label.ignore = !isNormalShown;
183	
184	        // TODO use setLabelStyle
185	        zrUtil.each(DISPLAY_STATES, (stateName) => {
186	
187	            const labelStateModel = stateName === 'normal' ? itemModel.getModel('label')
188	                : itemModel.getModel([stateName, 'label']);
189	            const isNormal = stateName === 'normal';
190	
191	            const state = isNormal ? label : label.ensureState(stateName);
192	            let text = seriesModel.getFormattedLabel(dataIndex, stateName);
193	            if (isNormal) {
194	                text = text || this.node.name;
195	            }
196	
197	            state.style = createTextStyle(labelStateModel, {}, null, stateName !== 'normal', true);
198	            if (text) {
199	                state.style.text = text;
200	            }
201	            // Not displaying text when angle is too small
202	            const isShown = labelStateModel.get('show');
203	            if (isShown != null && !isNormal) {
204	                state.ignore = !isShown;
205	            }
206	
207	            const labelPosition = getLabelAttr(labelStateModel, 'position');
208	
209	            const sectorState = isNormal ? sector : sector.states[stateName];
210	            const labelColor = sectorState.style.fill as ColorString;
211	            sectorState.textConfig = {
212	                outsideFill: labelStateModel.get('color') === 'inherit' ? labelColor : null,
213	                inside: labelPosition !== 'outside'
214	            };
215	
216	            let r;
217	            const labelPadding = getLabelAttr(labelStateModel, 'distance') || 0;
218	            let textAlign = getLabelAttr(labelStateModel, 'align');
219	            const rotateType = getLabelAttr(labelStateModel, 'rotate');
220	            const flipStartAngle = Math.PI * 0.5;
221	            const flipEndAngle = Math.PI * 1.5;
222	            const midAngleNormal = normalizeRadian(rotateType === 'tangential' ? Math.PI / 2 - midAngle : midAngle);
223	
224	            // For text that is up-side down, rotate 180 degrees to make sure
225	            // it's readable
226	            const needsFlip = midAngleNormal > flipStartAngle
227	                && !isRadianAroundZero(midAngleNormal - flipStartAngle)
228	                && midAngleNormal < flipEndAngle;
229	
230	            if (labelPosition === 'outside') {
231	                r = layout.r + labelPadding;
232	                textAlign = needsFlip ? 'right' : 'left';
233	            }
234	            else {
235	                if (!textAlign || textAlign === 'center') {
236	                    // Put label in the center if it's a circle
237	                    if (angle === 2 * Math.PI && layout.r0 === 0) {
238	                        r = 0;
239	                    }
240	                    else {
241	                        r = (layout.r + layout.r0) / 2;
242	                    }
243	                    textAlign = 'center';
244	                }
245	                else if (textAlign === 'left') {
246	                    r = layout.r0 + labelPadding;
247	                    textAlign = needsFlip ? 'right' : 'left';
248	                }
249	                else if (textAlign === 'right') {
250	                    r = layout.r - labelPadding;
251	                    textAlign = needsFlip ? 'left' : 'right';
252	                }
253	            }
254	
255	            state.style.align = textAlign;
256	            state.style.verticalAlign = getLabelAttr(labelStateModel, 'verticalAlign') || 'middle';
257	
258	            state.x = r * dx + layout.cx;
259	            state.y = r * dy + layout.cy;
260	
261	            let rotate = 0;
262	            if (rotateType === 'radial') {
263	                rotate = normalizeRadian(-midAngle)
264	                    + (needsFlip ? Math.PI : 0);
265	            }
266	            else if (rotateType === 'tangential') {
267	                rotate = normalizeRadian(Math.PI / 2 - midAngle)
268	                    + (needsFlip ? Math.PI : 0);
269	            }
270	            else if (zrUtil.isNumber(rotateType)) {
271	                rotate = rotateType * Math.PI / 180;
272	            }
273	
274	            state.rotation = normalizeRadian(rotate);
275	        });
276	
277	
278	        type LabelOpt = SunburstSeriesOption['label'];
279	        function getLabelAttr<T extends keyof LabelOpt>(model: Model<LabelOpt>, name: T): LabelOpt[T] {
280	            const stateAttr = model.get(name);
281	            if (stateAttr == null) {
282	                return normalLabelModel.get(name) as LabelOpt[T];
283	            }
284	            return stateAttr;
285	        }
286	
287	        label.dirtyStyle();
288	    }
289	}
290	
291	
292	export default SunburstPiece;
