20	import * as zrUtil from 'zrender/src/core/util';
21	import SeriesModel from '../../model/Series';
22	import Tree, { TreeNode } from '../../data/Tree';
23	import {wrapTreePathInfo} from '../helper/treeHelper';
24	import {
25	    SeriesOption,
26	    CircleLayoutOptionMixin,
27	    SeriesLabelOption,
28	    ItemStyleOption,
29	    OptionDataValue,
30	    CallbackDataParams,
31	    StatesOptionMixin,
32	    OptionDataItemObject,
33	    DefaultEmphasisFocus,
34	    SunburstColorByMixin
35	} from '../../util/types';
36	import GlobalModel from '../../model/Global';
37	import SeriesData from '../../data/SeriesData';
38	import Model from '../../model/Model';
39	import enableAriaDecalForTree from '../helper/enableAriaDecalForTree';
40	
41	interface SunburstItemStyleOption<TCbParams = never> extends ItemStyleOption<TCbParams> {
42	    // can be 10
43	    // which means that both innerCornerRadius and outerCornerRadius are 10
44	    // can also be an array [20, 10]
45	    // which means that innerCornerRadius is 20
46	    // and outerCornerRadius is 10
47	    // can also be a string or string array, such as ['20%', '50%']
48	    // which means that innerCornerRadius is 20% of the innerRadius
49	    // and outerCornerRadius is half of outerRadius.
50	    borderRadius?: (number | string)[] | number | string
51	}
52	
53	interface SunburstLabelOption extends Omit<SeriesLabelOption<SunburstDataParams>, 'rotate' | 'position'> {
54	    rotate?: 'radial' | 'tangential' | number
55	    minAngle?: number
56	    silent?: boolean
57	    position?: SeriesLabelOption['position'] | 'outside'
58	}
59	
60	interface SunburstDataParams extends CallbackDataParams {
61	    treePathInfo: {
62	        name: string,
63	        dataIndex: number
64	        value: SunburstSeriesNodeItemOption['value']
65	    }[]
66	}
67	
68	interface SunburstStatesMixin {
69	    emphasis?: {
70	        focus?: DefaultEmphasisFocus | 'descendant' | 'ancestor' | 'relative'
71	    }
72	}
73	
74	export interface SunburstStateOption<TCbParams = never> {
75	    itemStyle?: SunburstItemStyleOption<TCbParams>
76	    label?: SunburstLabelOption
77	}
78	
79	export interface SunburstSeriesNodeItemOption extends
80	    SunburstStateOption<SunburstDataParams>,
81	    StatesOptionMixin<SunburstStateOption<SunburstDataParams>, SunburstStatesMixin>,
82	    OptionDataItemObject<OptionDataValue>
83	{
