322	function completeTreeValue(dataNode: SunburstSeriesNodeItemOption) {
323	    // Postorder travel tree.
324	    // If value of none-leaf node is not set,
325	    // calculate it by suming up the value of all children.
326	    let sum = 0;
327	
328	    zrUtil.each(dataNode.children, function (child) {
329	
330	        completeTreeValue(child);
331	
332	        let childValue = child.value;
333	        // TODO First value of array must be a number
334	        zrUtil.isArray(childValue) && (childValue = childValue[0]);
335	        sum += childValue as number;
336	    });
337	
338	    let thisValue = dataNode.value as number;
339	    if (zrUtil.isArray(thisValue)) {
340	        thisValue = thisValue[0];
341	    }
342	
343	    if (thisValue == null || isNaN(thisValue)) {
344	        thisValue = sum;
345	    }
346	    // Value should not less than 0.
347	    if (thisValue < 0) {
348	        thisValue = 0;
349	    }
350	
351	    zrUtil.isArray(dataNode.value)
352	        ? (dataNode.value[0] = thisValue)
353	        : (dataNode.value = thisValue);
354	}
