21	import ChartView from '../../view/Chart';
22	import SunburstPiece from './SunburstPiece';
23	import DataDiffer from '../../data/DataDiffer';
24	import SunburstSeriesModel, { SunburstSeriesNodeItemOption } from './SunburstSeries';
25	import GlobalModel from '../../model/Global';
26	import ExtensionAPI from '../../core/ExtensionAPI';
27	import { TreeNode } from '../../data/Tree';
28	import { ROOT_TO_NODE_ACTION } from './sunburstAction';
29	import { windowOpen } from '../../util/format';
30	
31	interface DrawTreeNode extends TreeNode {
32	    parentNode: DrawTreeNode
33	    piece: SunburstPiece
34	    children: DrawTreeNode[]
35	}
36	class SunburstView extends ChartView {
37	
38	    static readonly type = 'sunburst';
39	    readonly type = SunburstView.type;
40	
41	    seriesModel: SunburstSeriesModel;
42	    api: ExtensionAPI;
43	    ecModel: GlobalModel;
44	
45	    virtualPiece: SunburstPiece;
46	
47	    private _oldChildren: DrawTreeNode[];
48	
49	    render(
50	        seriesModel: SunburstSeriesModel,
51	        ecModel: GlobalModel,
52	        api: ExtensionAPI,
53	        // @ts-ignore
54	        payload
55	    ) {
56	        const self = this;
57	
58	        this.seriesModel = seriesModel;
59	        this.api = api;
60	        this.ecModel = ecModel;
61	
62	        const data = seriesModel.getData();
63	        const virtualRoot = data.tree.root as DrawTreeNode;
64	
65	        const newRoot = seriesModel.getViewRoot() as DrawTreeNode;
66	
67	        const group = this.group;
68	
69	        const renderLabelForZeroData = seriesModel.get('renderLabelForZeroData');
70	
71	        const newChildren: DrawTreeNode[] = [];
72	        newRoot.eachNode(function (node: DrawTreeNode) {
73	            newChildren.push(node);
74	        });
75	        const oldChildren = this._oldChildren || [];
76	
77	        dualTravel(newChildren, oldChildren);
78	
79	        renderRollUp(virtualRoot, newRoot);
80	
81	        this._initEvents();
82	
83	        this._oldChildren = newChildren;
84	
85	        function dualTravel(newChildren: DrawTreeNode[], oldChildren: DrawTreeNode[]) {
86	            if (newChildren.length === 0 && oldChildren.length === 0) {
87	                return;
88	            }
89	
90	            new DataDiffer(oldChildren, newChildren, getKey, getKey)
91	                .add(processNode)
92	                .update(processNode)
93	                .remove(zrUtil.curry(processNode, null))
94	                .execute();
95	
96	            function getKey(node: DrawTreeNode) {
97	                return node.getId();
98	            }
99	
100	            function processNode(newIdx: number, oldIdx?: number) {
101	                const newNode = newIdx == null ? null : newChildren[newIdx];
102	                const oldNode = oldIdx == null ? null : oldChildren[oldIdx];
103	
104	                doRenderNode(newNode, oldNode);
105	            }
106	        }
107	
108	        function doRenderNode(newNode: DrawTreeNode, oldNode: DrawTreeNode) {
109	            if (!renderLabelForZeroData && newNode && !newNode.getValue()) {
110	                // Not render data with value 0
111	                newNode = null;
112	            }
113	
114	            if (newNode !== virtualRoot && oldNode !== virtualRoot) {
115	                if (oldNode && oldNode.piece) {
116	                    if (newNode) {
117	                        // Update
118	                        oldNode.piece.updateData(
119	                            false, newNode, seriesModel, ecModel, api
120	                        );
121	
122	                        // For tooltip
123	                        data.setItemGraphicEl(newNode.dataIndex, oldNode.piece);
124	                    }
125	                    else {
126	                        // Remove
127	                        removeNode(oldNode);
128	                    }
129	                }
130	                else if (newNode) {
131	                    // Add
132	                    const piece = new SunburstPiece(
133	                        newNode,
134	                        seriesModel,
135	                        ecModel,
136	                        api
137	                    );
138	                    group.add(piece);
139	
140	                    // For tooltip
141	                    data.setItemGraphicEl(newNode.dataIndex, piece);
142	                }
143	            }
144	        }
145	
146	        function removeNode(node: DrawTreeNode) {
147	            if (!node) {
148	                return;
149	            }
150	
151	            if (node.piece) {
152	                group.remove(node.piece);
153	                node.piece = null;
154	            }
155	        }
156	
157	        function renderRollUp(virtualRoot: DrawTreeNode, viewRoot: DrawTreeNode) {
158	            if (viewRoot.depth > 0) {
159	                // Render
160	                if (self.virtualPiece) {
161	                    // Update
162	                    self.virtualPiece.updateData(
163	                        false, virtualRoot, seriesModel, ecModel, api
164	                    );
165	                }
166	                else {
167	                    // Add
168	                    self.virtualPiece = new SunburstPiece(
169	                        virtualRoot,
170	                        seriesModel,
171	                        ecModel,
172	                        api
173	                    );
174	                    group.add(self.virtualPiece);
175	                }
176	
177	                // TODO event scope
178	                viewRoot.piece.off('click');
179	                self.virtualPiece.on('click', function (e) {
180	                    self._rootToNode(viewRoot.parentNode);
181	                });
182	            }
183	            else if (self.virtualPiece) {
184	                // Remove
185	                group.remove(self.virtualPiece);
186	                self.virtualPiece = null;
187	            }
188	        }
189	    }
190	
191	    /**
192	     * @private
193	     */
194	    _initEvents() {
195	        this.group.off('click');
196	        this.group.on('click', (e) => {
197	            let targetFound = false;
198	            const viewRoot = this.seriesModel.getViewRoot();
199	            viewRoot.eachNode((node: DrawTreeNode) => {
200	                if (!targetFound
201	                    && node.piece && node.piece === e.target
202	                ) {
203	                    const nodeClick = node.getModel<SunburstSeriesNodeItemOption>().get('nodeClick');
204	                    if (nodeClick === 'rootToNode') {
205	                        this._rootToNode(node);
206	                    }
207	                    else if (nodeClick === 'link') {
208	                        const itemModel = node.getModel<SunburstSeriesNodeItemOption>();
209	                        const link = itemModel.get('link');
210	                        if (link) {
211	                            const linkTarget = itemModel.get('target', true)
212	                                || '_blank';
213	                            windowOpen(link, linkTarget);
214	                        }
215	                    }
216	                    targetFound = true;
217	                }
218	            });
219	        });
220	    }
221	
222	    /**
223	     * @private
224	     */
225	    _rootToNode(node: DrawTreeNode) {
226	        if (node !== this.seriesModel.getViewRoot()) {
227	            this.api.dispatchAction({
228	                type: ROOT_TO_NODE_ACTION,
229	                from: this.uid,
230	                seriesId: this.seriesModel.id,
231	                targetNode: node
232	            });
233	        }
234	    }
235	
236	    /**
237	     * @implement
238	     */
239	    containPoint(point: number[], seriesModel: SunburstSeriesModel) {
240	        const treeRoot = seriesModel.getData();
241	        const itemLayout = treeRoot.getItemLayout(0);
242	        if (itemLayout) {
243	            const dx = point[0] - itemLayout.cx;
244	            const dy = point[1] - itemLayout.cy;
245	            const radius = Math.sqrt(dx * dx + dy * dy);
246	            return radius <= itemLayout.r && radius >= itemLayout.r0;
247	        }
248	    }
249	
250	}
251	
252	export default SunburstView;
